from pathlib import Path
from html import escape
from flamegraph_proofs import load_proof_index, render_proof_card
root=Path(r'C:/VoxxedDays')
out=root/'talk_examples_overview.html'
proof_index=load_proof_index(root)

def sn(rel,start,end):
    lines=(root/rel).read_text(encoding='utf-8').splitlines()
    return '\n'.join(f"{i:4d}: {lines[i-1]}" for i in range(start,end+1) if 1<=i<=len(lines))

def render_commit_block(ex):
    commit_links=''.join(f"<a href='{escape(url)}' target='_blank' rel='noopener'>{escape(label)}</a>" for label,url in ex['commit_links'])
    return (
        "<div class='mini-card'><h6>Commit Provenance And Story Fit</h6>"
        "<div class='link-list'>" + commit_links + "</div>"
        f"<p><strong>Commit validation:</strong> {ex['provenance']}</p>"
        f"<p><strong>Functional explanation:</strong> {ex['functional_story']}</p>"
        f"<p><strong>Why 10%+ is plausible:</strong> {ex['improvement_case']}</p>"
        "</div>"
    )

